    // COM2 and MIDI are not wired on this board yet; idle receive lines.
    wire midi_rx = 1'b1;
    wire midi_tx;
    wire uart2_rx = 1'b1;
    wire uart2_cts_n = 1'b1;
    wire uart2_dsr_n = 1'b1;
    wire uart2_dcd_n = 1'b1;
    wire uart2_tx;
    wire uart2_rts_n;
    wire uart2_dtr_n;

    logic [1:0]  midi_baud_div_q;
    logic [25:0] uart_baud_phase_q;
    logic        midi_baudce;
    logic        uart_baudce;
    always_ff @(posedge CLK_50M or posedge RESET) begin
        if (RESET) begin
            midi_baud_div_q  <= 2'd0;
            midi_baudce      <= 1'b0;
            uart_baud_phase_q <= 26'd0;
            uart_baudce      <= 1'b0;
        end else begin
            midi_baudce <= (midi_baud_div_q == 2'd3);
            if (midi_baud_div_q == 2'd3)
                midi_baud_div_q <= 2'd0;
            else
                midi_baud_div_q <= midi_baud_div_q + 1'b1;

            if ((uart_baud_phase_q + 26'd1_843_200) >= 26'd50_000_000) begin
                uart_baud_phase_q <= uart_baud_phase_q + 26'd1_843_200 -
                                     26'd50_000_000;
                uart_baudce <= 1'b1;
            end else begin
                uart_baud_phase_q <= uart_baud_phase_q + 26'd1_843_200;
                uart_baudce <= 1'b0;
            end
        end
    end

    wire        physical_idle;
    wire [12:0] sdram_address;
    wire        sdram_cke;
    wire        sdram_cs;
    wire        sdram_ras;
    wire        sdram_cas;
    wire        sdram_we;
    wire [1:0]  sdram_ba;
    wire [15:0] sdram_dq_in;
    wire [15:0] sdram_dq_out;
    wire        sdram_dq_io;
    wire        sdram_ldqm;
    wire        sdram_udqm;
